-- 147: Original BrillaPrep WASSCE BrillaPrep transitional Auto Mechanics beta content blueprint questions, part 5.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_147_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_147_guard;
INSERT INTO _migration_147_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_021' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_5' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does a hydrometer measure in a serviceable lead-acid vehicle battery?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The relative density of the electrolyte","B. Battery terminal voltage","C. Electrolyte temperature","D. Starter current draw"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Electrolyte relative density provides an indication of state of charge and cell condition when temperature and battery design are considered. Therefore the correct answer is A: The relative density of the electrolyte.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_021' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_147_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_022' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_5' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the starter motor’s function during engine starting?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Turn the alternator fast enough to charge the battery","B. Crank the engine fast enough for combustion to begin","C. Preheat the intake air before cranking","D. Advance ignition timing until combustion begins"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The starter converts battery electrical energy into torque at the flywheel until the engine can sustain its own combustion cycle. Therefore the correct answer is B: Crank the engine fast enough for combustion to begin.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_022' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_147_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_023' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_5' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the alternator’s main function while the engine is running?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Provide all cranking torque to the flywheel","B. Supply the ignition system only while starting","C. Supply electrical loads and recharge the battery","D. Regulate battery electrolyte density"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The belt-driven alternator generates electrical power, and its regulator controls charging voltage for the battery and vehicle systems. Therefore the correct answer is C: Supply electrical loads and recharge the battery.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_023' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_147_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_024' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_5' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a spark-ignition engine, what does the ignition coil provide?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A high current at approximately battery voltage","B. A timed low-voltage pulse at the plug gap","C. A steady charging voltage for the starter motor","D. A high voltage capable of producing a spark across the plug gap"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The coil transforms the low battery voltage into a high-voltage pulse so current can cross the spark-plug gap at the required time. Therefore the correct answer is D: A high voltage capable of producing a spark across the plug gap.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_024' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_147_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_025' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_5' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A battery reads about 12.6 V at rest but voltage collapses during cranking. What is the best next check?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Perform a battery load test and inspect high-current connections","B. Check alternator output before testing the battery","C. Replace the starter without a voltage-drop test","D. Clean the spark plugs before checking the cables"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A normal open-circuit voltage can coexist with poor capacity or high connection resistance, which a load test and voltage-drop checks reveal. Therefore the correct answer is A: Perform a battery load test and inspect high-current connections.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_025' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
